"""Form Five English, Term One. Row 1 diagnostic excluded; oral rows teach written preparation."""
import json
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import lessonlib as L
import banks_en as B
from lessonlib import card,worked,learn,num,mcq
L.use_class("form-5","Form 5")
OUT=L.ROOT/"english"
SRC=["english"]
PATH=[]

def F(term,meaning,case,error,why): return dict(term=term,meaning=meaning,case=case,error=error,why=why)
def item(q,r,wrong,why):
    assert len(wrong)==3
    return dict(q=q,r=r,w=[x[0] for x in wrong],e=[x[1] for x in wrong],y=why)
def qa(n,key,level,items): return B.QA(f"e5-{n}-{key}",level,"{X.q}",items,SRC)
def choose(n,rows,level=2,key="apply"):
    return qa(n,key,level,[item(q,r,list(zip(w,e)),why) for q,r,w,e,why in rows])
def word_order(n,sentences): return B.WO(f"e5-{n}-build",2,sentences,SRC)

def unit(n,title,goal,back,next_use,note,case,method,facts,applied,prereq=(),paper=None,extra=None,example=None):
    assert 4 <= len(facts) <= 6
    terms=[]; cases=[]
    for i,f in enumerate(facts):
        other=[x for j,x in enumerate(facts) if j!=i][:3]
        terms.append(item("Which term means "+f["meaning"]+"?",f["term"],[(x["term"],"That concerns "+x["meaning"]+", rather than "+f["meaning"]+".") for x in other],f["why"]))
        cases.append(item(f["case"]+"\nWhich description best fits the selected feature?",f["term"],[(x["term"],"That means "+x["meaning"]+". The selected feature instead illustrates "+f["meaning"]+".") for x in other],f["why"]))
    q0=qa(n,"terms",1,terms); q1=qa(n,"cases",1,cases)
    q3=extra or B.MT(f"e5-{n}-link",2,"Match each term to its example.",[(f["term"],f["case"]) for f in facts],SRC,pick=3)
    q4=B.SP(f"e5-{n}-repair",3,"Find the incorrect claim or language form.",[f["term"]+": "+f["meaning"]+"." for f in facts],[(f["error"],f["why"]) for f in facts],SRC)
    for st,f in zip(q4["pool"]["right"],facts): st["explain"]="This is correct: "+f["meaning"]+". Look for a claim that conflicts with a rule or distinction taught in Learn."
    questions=[q0,q1,applied,q3,q4]
    cards=[card(f"e5-{n}-c1","Distinguish the ideas used in this lesson.",[f["term"]+": "+f["meaning"]+"." for f in facts],q0["id"]),
       card(f"e5-{n}-c2","Read the whole example before identifying its function.",[f["case"] for f in facts],q1["id"]),
       card(f"e5-{n}-c3","A correction must preserve the intended meaning and form.",[f["error"]+" Correction: "+f["why"] for f in facts],q4["id"])]
    L.lesson("english","english-language",n,(f"e5-{n}",title),prereq,note,
       example or worked({},facts[0]["case"]+" Explain the selected feature.",[facts[0]["meaning"].capitalize()+".",facts[0]["why"]],facts[0]["term"]),cards,questions,paper=paper,
       learn=learn([("Your goal and connections","By the end, you should be able to "+goal+". Builds on: "+back+". Leads to: "+next_use+"."),
         ("Understand the pattern",note),("Read the original model",case),("Apply and check",method)],
         key_words=[(f["term"],f["meaning"]) for f in facts],mistake=(facts[0]["error"],facts[0]["term"]+": "+facts[0]["meaning"]+".",facts[0]["why"])))
    PATH.append((n,title,goal,back,next_use))

def reuse(n,source,title,goal,back,next_use,prereq):
    obj=json.loads((L.ROOT.parent/'form-4/english'/f'{source}.json').read_text(encoding='utf-8'))
    obj=json.loads(json.dumps(obj,ensure_ascii=False).replace(f'e4-{source}',f'e5-{n}'))
    obj.update(lesson_no=n,**{'class':'Form 5'},prerequisites=prereq)
    obj['skills'][0]['name']=title
    obj['learn']['sections'][0]['text']='By the end, you should be able to '+goal+'. Builds on: '+back+'. Leads to: '+next_use+'.'
    L.write('english',n,obj);PATH.append((n,title,goal,back,next_use))

def writing(n,title,goal,back,next_use,note,model,method,facts,prompt,checks,prereq=()):
    unit(n,title,goal,back,next_use,note,'Original model extract: '+model[0],method,facts,
      word_order(n,[f['case'] for f in facts]),prereq,
      paper=dict(vars={},checks=[],prompt=prompt,model=model,checklist=checks))

def reading(n,title,goal,back,next_use,script,rows,prereq,oral=False):
    unit(n,title,goal,back,next_use,
      'Read the whole passage before answering. Separate directly stated facts, reasons, proposals and information that remains unknown. An inference needs an identifiable clue and must not turn a fictional case into a universal claim. Notice who speaks and whether a statement is an opinion, a plan or an observed result. '+('This is a written script for listening preparation: no recording is supplied and no hearing or speaking is assessed.' if oral else 'The passage is original classroom fiction, not a report about a real named organisation.'),
      script,'Locate the relevant sentence, state your answer and identify its support. Check whether a question asks what happened, why, or what cannot be concluded. '+('Then use a teacher-provided oral reading for real listening practice if available.' if oral else 'Do not add a result or private detail that the passage does not provide.'),[
      F('explicit information','a detail directly supplied in the passage','A stated role or action can be located in the text.','Any plausible invented detail is explicitly stated.','The detail must actually be present.'),
      F('supported inference','a conclusion grounded in a relevant textual clue','A request to verify a source suggests that confirmation is still needed.','Every guess is equally supported regardless of the wording.','The conclusion needs an appropriate clue.'),
      F('proposal','an action suggested rather than necessarily completed','Planning a meeting does not show its eventual attendance.','Every proposed action is a measured success already.','Intention and result are different.'),
      F('limit of evidence','what this passage cannot establish','An absent outcome must remain unknown.','One invented case proves every real community behaves identically.','The evidence does not carry that universal scope.')],choose(n,rows,key='comprehend'),prereq)

